def transform(grid):
    from collections import Counter, deque

    # Find background color (most frequent)
    pixels = [p for row in grid for p in row]
    counts = Counter(pixels)
    bg = counts.most_common(1)[0][0]

    result = [row[:] for row in grid]

    # Find all non-bg colors
    for color in counts:
        if color == bg:
            continue

        # Find connected components of this color using 4-connectivity
        visited = set()

        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color and (r, c) not in visited:
                    # BFS to find connected component
                    component = []
                    queue = deque([(r, c)])
                    visited.add((r, c))
                    while queue:
                        curr_r, curr_c = queue.popleft()
                        component.append((curr_r, curr_c))

                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if grid[nr][nc] == color and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    queue.append((nr, nc))

                    # Find bounding box of this component
                    rows = [p[0] for p in component]
                    cols = [p[1] for p in component]
                    min_r, max_r = min(rows), max(rows)
                    min_c, max_c = min(cols), max(cols)

                    # For 180-degree rotation: (r, c) -> (min_r + max_r - r, min_c + max_c - c)
                    for pr, pc in component:
                        mr = min_r + max_r - pr
                        mc = min_c + max_c - pc

                        if 0 <= mr < len(grid) and 0 <= mc < len(grid[0]):
                            if result[mr][mc] == bg:
                                result[mr][mc] = color

    return result
